import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import {
  Editor,
  type EditorTheme,
  Key,
  matchesKey,
  Text,
  visibleWidth,
  wrapTextWithAnsi,
} from "@earendil-works/pi-tui";
import { Type, type Static } from "typebox";
import {
  ASK_USER_PARAMETER_DESCRIPTIONS,
  ASK_USER_PROMPT_GUIDELINES,
  ASK_USER_PROMPT_SNIPPET,
  ASK_USER_TOOL_DESCRIPTION,
  buildAskUserResultMessage,
  MAX_OPTIONS,
  MIN_OPTIONS,
} from "./prompt.ts";
import { notifyAskUser } from "./notify.ts";

const OptionSchema = Type.Object({
  label: Type.String({
    description: ASK_USER_PARAMETER_DESCRIPTIONS.optionLabel,
  }),
  description: Type.Optional(
    Type.String({
      description: ASK_USER_PARAMETER_DESCRIPTIONS.optionDescription,
    }),
  ),
});

const AskUserParameters = Type.Object({
  question: Type.String({
    description: ASK_USER_PARAMETER_DESCRIPTIONS.question,
  }),
  options: Type.Array(OptionSchema, {
    minItems: MIN_OPTIONS,
    maxItems: MAX_OPTIONS,
    description: ASK_USER_PARAMETER_DESCRIPTIONS.options,
  }),
});

export type AskUserInput = Static<typeof AskUserParameters>;

interface AskUserDetails {
  question: string;
  options: string[];
  answer: string | null;
  wasCustom: boolean;
  cancelled: boolean;
}

interface DisplayOption {
  label: string;
  description?: string;
  isOther?: boolean;
}

type SelectionResult =
  | { answer: string; wasCustom: true }
  | { answer: string; wasCustom: false; index: number }
  | null;

export default function askUser(pi: ExtensionAPI): void {
  pi.registerTool({
    name: "ask_user",
    label: "Ask User",
    description: ASK_USER_TOOL_DESCRIPTION,
    promptSnippet: ASK_USER_PROMPT_SNIPPET,
    promptGuidelines: ASK_USER_PROMPT_GUIDELINES,
    parameters: AskUserParameters,
    executionMode: "sequential",

    async execute(_toolCallId, params, signal, _onUpdate, ctx) {
      const reply = (
        text: string,
        answer: string | null = null,
        wasCustom = false,
      ) => ({
        content: [{ type: "text" as const, text }],
        details: {
          question: params.question,
          options: params.options.map((option) => option.label),
          answer,
          wasCustom,
          cancelled: answer === null,
        } satisfies AskUserDetails,
      });

      if (
        params.options.length < MIN_OPTIONS ||
        params.options.length > MAX_OPTIONS
      ) {
        throw new Error(
          `ask_user requires ${MIN_OPTIONS}-${MAX_OPTIONS} options; received ${params.options.length}.`,
        );
      }

      if (ctx.mode !== "tui") {
        return reply(buildAskUserResultMessage({ kind: "no-ui" }));
      }
      if (signal?.aborted) {
        return reply(buildAskUserResultMessage({ kind: "cancelled" }));
      }

      notifyAskUser(
        params.question,
        params.options.map((option) => option.label),
      );

      const options: DisplayOption[] = [
        ...params.options,
        { label: "Write my own answer…", isOther: true },
      ];
      let interrupted = false;

      const result = await ctx.ui.custom<SelectionResult>(
        (tui, theme, _keybindings, done) => {
          let optionIndex = 0;
          let editMode = false;
          let settled = false;
          let focused = false;
          let cachedWidth: number | undefined;
          let cachedLines: string[] | undefined;

          const editorTheme: EditorTheme = {
            borderColor: (text) => theme.fg("accent", text),
            selectList: {
              selectedPrefix: (text) => theme.fg("accent", text),
              selectedText: (text) => theme.fg("accent", text),
              description: (text) => theme.fg("muted", text),
              scrollInfo: (text) => theme.fg("dim", text),
              noMatch: (text) => theme.fg("warning", text),
            },
          };
          const editor = new Editor(tui, editorTheme);

          const cleanup = () => signal?.removeEventListener("abort", abort);
          const finish = (value: SelectionResult) => {
            if (settled) return;
            settled = true;
            cleanup();
            done(value);
          };
          const abort = () => {
            interrupted = true;
            finish(null);
          };
          signal?.addEventListener("abort", abort, { once: true });
          if (signal?.aborted) queueMicrotask(abort);

          const refresh = () => {
            cachedWidth = undefined;
            cachedLines = undefined;
            tui.requestRender();
          };

          const selectOption = (index: number) => {
            const selected = options[index];
            if (!selected) return;
            if (selected.isOther) {
              optionIndex = index;
              editMode = true;
              refresh();
              return;
            }
            finish({
              answer: selected.label,
              wasCustom: false,
              index: index + 1,
            });
          };

          editor.onSubmit = (value) => {
            const answer = value.trim();
            if (answer) {
              finish({ answer, wasCustom: true });
              return;
            }
            editMode = false;
            editor.setText("");
            refresh();
          };

          const handleInput = (data: string) => {
            if (editMode) {
              if (matchesKey(data, Key.escape)) {
                editMode = false;
                editor.setText("");
                refresh();
                return;
              }
              editor.handleInput(data);
              refresh();
              return;
            }

            if (matchesKey(data, Key.up)) {
              optionIndex =
                (optionIndex - 1 + options.length) % options.length;
              refresh();
              return;
            }
            if (matchesKey(data, Key.down)) {
              optionIndex = (optionIndex + 1) % options.length;
              refresh();
              return;
            }
            if (
              data.length === 1 &&
              data >= "1" &&
              data <= String(options.length)
            ) {
              selectOption(Number(data) - 1);
              return;
            }
            if (matchesKey(data, Key.enter)) {
              selectOption(optionIndex);
              return;
            }
            if (matchesKey(data, Key.escape)) finish(null);
          };

          const render = (width: number): string[] => {
            const renderWidth = Math.max(1, width);
            if (cachedLines && cachedWidth === renderWidth) return cachedLines;

            const lines: string[] = [];
            const addWrapped = (prefix: string, text: string) => {
              const prefixWidth = visibleWidth(prefix);
              if (prefixWidth >= renderWidth) {
                lines.push(...wrapTextWithAnsi(prefix + text, renderWidth));
                return;
              }
              const wrapped = wrapTextWithAnsi(
                text,
                Math.max(1, renderWidth - prefixWidth),
              );
              const continuation = " ".repeat(prefixWidth);
              wrapped.forEach((line, index) => {
                lines.push(`${index === 0 ? prefix : continuation}${line}`);
              });
            };

            lines.push(theme.fg("accent", "─".repeat(renderWidth)));
            addWrapped(" ", theme.fg("text", theme.bold(params.question)));
            lines.push("");

            options.forEach((option, index) => {
              const selected = index === optionIndex;
              const prefix = selected ? theme.fg("accent", " ❯ ") : "   ";
              const marker = option.isOther ? "✎" : `${index + 1}.`;
              const color = selected ? "accent" : option.isOther ? "muted" : "text";
              addWrapped(prefix, theme.fg(color, `${marker} ${option.label}`));
              if (option.description) {
                addWrapped("      ", theme.fg("muted", option.description));
              }
            });

            if (editMode) {
              lines.push("");
              addWrapped(" ", theme.fg("muted", "Your answer:"));
              for (const line of editor.render(Math.max(1, renderWidth - 2))) {
                lines.push(` ${line}`);
              }
            }

            lines.push("");
            addWrapped(
              " ",
              theme.fg(
                "dim",
                editMode
                  ? "Enter submit • Esc back"
                  : `↑↓ or 1-${options.length} select • Enter confirm • Esc dismiss`,
              ),
            );
            lines.push(theme.fg("accent", "─".repeat(renderWidth)));

            cachedWidth = renderWidth;
            cachedLines = lines;
            return lines;
          };

          return {
            get focused() {
              return focused;
            },
            set focused(value: boolean) {
              focused = value;
              editor.focused = value;
            },
            render,
            handleInput,
            invalidate() {
              cachedWidth = undefined;
              cachedLines = undefined;
              editor.invalidate();
            },
            dispose: cleanup,
          };
        },
      );

      if (interrupted || signal?.aborted) {
        return reply(buildAskUserResultMessage({ kind: "cancelled" }));
      }
      if (!result) {
        return reply(buildAskUserResultMessage({ kind: "dismissed" }));
      }
      if (result.wasCustom) {
        return reply(
          buildAskUserResultMessage({ kind: "custom", answer: result.answer }),
          result.answer,
          true,
        );
      }
      return reply(
        buildAskUserResultMessage({
          kind: "selected",
          answer: result.answer,
          index: result.index,
        }),
        result.answer,
      );
    },

    renderCall(args, theme) {
      const question = typeof args.question === "string" ? args.question : "";
      const options = Array.isArray(args.options)
        ? (args.options as DisplayOption[])
        : [];
      const labels = options.map((option, index) => `${index + 1}. ${option.label}`);
      let text = theme.fg("toolTitle", theme.bold("ask_user "));
      text += theme.fg("muted", question);
      if (labels.length > 0) text += `\n${theme.fg("dim", `  ${labels.join("  ")}`)}`;
      return new Text(text, 0, 0);
    },

    renderResult(result, _options, theme) {
      const details = result.details as AskUserDetails | undefined;
      if (!details) {
        const first = result.content[0];
        return new Text(first?.type === "text" ? first.text : "", 0, 0);
      }
      if (details.cancelled || details.answer === null) {
        return new Text(theme.fg("warning", "✗ dismissed"), 0, 0);
      }
      if (details.wasCustom) {
        return new Text(
          `${theme.fg("success", "✓ ")}${theme.fg("muted", "(wrote) ")}${theme.fg("accent", details.answer)}`,
          0,
          0,
        );
      }
      const index = details.options.indexOf(details.answer) + 1;
      const answer = index > 0 ? `${index}. ${details.answer}` : details.answer;
      return new Text(
        `${theme.fg("success", "✓ ")}${theme.fg("accent", answer)}`,
        0,
        0,
      );
    },
  });
}

