export const MIN_OPTIONS = 2;
export const MAX_OPTIONS = 5;

export const ASK_USER_PARAMETER_DESCRIPTIONS = {
  optionLabel: "Short display label for this option",
  optionDescription: "Optional one-line description shown below the label",
  question: "The single question to ask the user",
  options:
    "Between 2 and 5 answer options. A free-form answer option is appended automatically; do not add one yourself.",
};

export const ASK_USER_TOOL_DESCRIPTION =
  "Ask the user one multiple-choice question with 2-5 options. A free-form answer is always available, and the user may dismiss the question without answering.";

export const ASK_USER_PROMPT_SNIPPET =
  "Ask one multiple-choice question with a free-form fallback";

export const ASK_USER_PROMPT_GUIDELINES = [
  "Use ask_user when a necessary user decision has a small enumerable answer set.",
  "Ask exactly one question per ask_user call; use another call for a follow-up question.",
  "Do not use ask_user when a reasonable default exists and the task can proceed safely without interrupting the user.",
];

export type AskUserOutcome =
  | { kind: "no-ui" }
  | { kind: "cancelled" }
  | { kind: "dismissed" }
  | { kind: "custom"; answer: string }
  | { kind: "selected"; answer: string; index: number };

export function buildAskUserResultMessage(outcome: AskUserOutcome): string {
  switch (outcome.kind) {
    case "no-ui":
      return "No interactive UI is available. Ask the user in plain text instead.";
    case "cancelled":
      return "The question was cancelled.";
    case "dismissed":
      return "The user dismissed the question without answering. Do not infer an answer.";
    case "custom":
      return `The user wrote: ${outcome.answer}`;
    case "selected":
      return `The user selected option ${outcome.index}: ${outcome.answer}`;
  }
}

