import { homedir } from "node:os";
import { join } from "node:path";
import { readFileSync } from "node:fs";

export const DEFAULT_NTFY_ENV_PATH = join(homedir(), ".secrets", "ntfy", "env");
export const DEFAULT_NOTIFY_TITLE = "Pi 在等你回答";
const REQUEST_TIMEOUT_MS = 3000;

export interface NotifyConfig {
  enabled: boolean;
  url: string;
  token: string;
  topic: string;
}

export interface NotifyPayload {
  title: string;
  message: string;
  priority: "high";
}

export function isTruthy(value: string | undefined): boolean {
  if (!value) return false;
  return ["1", "true", "on", "yes"].includes(value.trim().toLowerCase());
}

export function parseEnvFile(text: string): Record<string, string> {
  const result: Record<string, string> = {};
  for (const rawLine of text.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith("#")) continue;
    const match = line.match(/^(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)=(.*)$/);
    if (!match) continue;
    const [, key, rawValue] = match;
    result[key] = stripQuotes(rawValue.trim());
  }
  return result;
}

function stripQuotes(value: string): string {
  if (
    (value.startsWith('"') && value.endsWith('"')) ||
    (value.startsWith("'") && value.endsWith("'"))
  ) {
    return value.slice(1, -1);
  }
  return value;
}

export function readEnvFile(path = process.env.ASK_USER_NTFY_ENV ?? DEFAULT_NTFY_ENV_PATH): Record<string, string> {
  try {
    return parseEnvFile(readFileSync(path, "utf8"));
  } catch {
    return {};
  }
}

export function resolveNotifyConfig(
  env: NodeJS.ProcessEnv | Record<string, string | undefined> = process.env,
  fileVars: Record<string, string> = {},
): NotifyConfig {
  const pick = (key: string): string => {
    const fromEnv = env[key];
    if (typeof fromEnv === "string" && fromEnv.trim()) return fromEnv.trim();
    return (fileVars[key] ?? "").trim();
  };

  return {
    enabled: isTruthy(pick("ASK_USER_NOTIFY")),
    url: pick("NTFY_URL").replace(/\/+$/, ""),
    token: pick("NTFY_TOKEN"),
    topic: pick("NTFY_TOPIC") || "alerts",
  };
}

export function canNotify(config: NotifyConfig): boolean {
  return Boolean(config.enabled && config.url && config.token && config.topic);
}

export function formatNotifyPayload(question: string, options: string[]): NotifyPayload {
  const lines = [question.trim(), ""];
  options.forEach((option, index) => {
    lines.push(`${index + 1}. ${option}`);
  });
  return {
    title: DEFAULT_NOTIFY_TITLE,
    message: lines.join("\n").trim(),
    priority: "high",
  };
}

export async function sendAskUserNotification(
  question: string,
  options: string[],
  config: NotifyConfig = resolveNotifyConfig(process.env, readEnvFile()),
): Promise<boolean> {
  if (!canNotify(config)) return false;

  const payload = formatNotifyPayload(question, options);
  const endpoint = `${config.url}/${encodeURIComponent(config.topic)}`;
  const response = await fetch(endpoint, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${config.token}`,
      Title: payload.title,
      Priority: payload.priority,
      Tags: "question",
    },
    body: payload.message,
    signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
  });
  return response.ok;
}

export function notifyAskUser(question: string, options: string[]): void {
  void sendAskUserNotification(question, options).catch(() => undefined);
}
